# PRE-COMPILED PATTERN ENGINE
# ═══════════════════════════════════════════════════════════════════════════

# Type alias for compiled pattern structure
CompiledPattern = Tuple[Pattern[str], str]
CompiledPatternMap = Dict[FallacyType, List[CompiledPattern]]


def _validate_pattern_safety(pattern: str) -> None:
    """
    Validate regex pattern for ReDoS (Regular Expression Denial of Service) risk.
    
    Rejects patterns with nested quantifiers or catastrophic backtracking potential.
    
    Args:
        pattern: The regex pattern string to validate.
        
    Raises:
        ValueError: If the pattern is deemed unsafe.
    """
    # Check for nested quantifiers (e.g., (a*)*, (a+)+)
    if re.search(r"\([^)]*\*[^)]*\)\s*[*+]", pattern):
        raise ValueError(f"Potentially unsafe regex pattern (nested quantifier): {pattern}")
    # Check for overlapping quantifiers
    if re.search(r"(\*|\+|\{)\s*(\*|\+|\{)", pattern):
        raise ValueError(f"Potentially unsafe regex pattern (overlapping quantifiers): {pattern}")
    # Check for excessive repetition counts
    if re.search(r"\{\d{3,}\}", pattern):
        raise ValueError(f"Potentially unsafe regex pattern (excessive repetition): {pattern}")


def _compile_patterns() -> CompiledPatternMap:
    """
    Compile all fallacy patterns at module load time.
    
    Returns:
        A dictionary mapping FallacyType to a list of (compiled_pattern, description) tuples.
        
    Raises:
        ValueError: If any pattern fails validation or compilation.
    """
    compiled: CompiledPatternMap = {}
    for fallacy_type, patterns in FALLACY_PATTERNS.items():
        compiled_list: List[CompiledPattern] = []
        for pattern_str, description in patterns:
            _validate_pattern_safety(pattern_str)
            try:
                compiled_pattern = re.compile(pattern_str, re.IGNORECASE)
            except re.error as e:
                logger.error("Failed to compile pattern for %s: %s", fallacy_type, e)
                raise ValueError(f"Invalid regex pattern for {fallacy_type}: {pattern_str}") from e
            compiled_list.append((compiled_pattern, description))
        compiled[fallacy_type] = compiled_list
    return compiled


# Compile once at module load — zero runtime compilation cost
COMPILED_FALLACY_PATTERNS: Final[CompiledPatternMap] = _compile_patterns()


class FallacyMatcher:
    """
    High-throughput fallacy detection engine.
    
    Uses pre-compiled regex patterns with early termination and
    batch processing capabilities for optimal performance.
    """
    
    __slots__ = ("_patterns", "_max_pattern_length", "_suggestions")
    
    def __init__(self, patterns: Optional[CompiledPatternMap] = None) -> None:
        """
        Initialize the matcher with compiled patterns.
        
        Args:
            patterns: Optional pre-compiled pattern map. Defaults to module-level
                     COMPILED_FALLACY_PATTERNS.
        """
        self._patterns = patterns or COMPILED_FALLACY_PATTERNS
        # Precompute the longest pattern length for early termination
        self._max_pattern_length = max(
            len(p.pattern) for patterns_list in self._patterns.values() 
            for p, _ in patterns_list
        )
        self._suggestions = self._build_suggestion_map()
    
    @staticmethod
    def _build_suggestion_map() -> Dict[FallacyType, str]:
        """Build remediation suggestions for each fallacy type."""
        return {
            FallacyType.CIRCULAR_REASONING: "Provide independent evidence for the conclusion.",
            FallacyType.FALSE_DICHOTOMY: "List all possible alternatives, not just two extremes.",
            FallacyType.HASTY_GENERALIZATION: "Gather more data before making universal claims.",
            FallacyType.APPEAL_TO_AUTHORITY: "Provide specific, verifiable sources for claims.",
            FallacyType.SLIPPERY_SLOPE: "Provide evidence for each step in the causal chain.",
            FallacyType.STRAW_MAN: "Address the actual argument, not a distorted version.",
            FallacyType.AD_HOMINEM: "Focus on the argument's merits, not personal characteristics.",
            FallacyType.RED_HERRING: "Stay on topic and address the original question.",
            FallacyType.POST_HOC: "Establish causation beyond temporal correlation.",
            FallacyType.BEGGING_THE_QUESTION: "Provide independent justification for premises.",
            FallacyType.EQUIVOCATION: "Define terms clearly and use them consistently.",
            FallacyType.APPEAL_TO_EMOTION: "Support claims with factual evidence, not emotion.",
            FallacyType.NON_SEQUITUR: "Ensure the conclusion logically follows from premises.",
            FallacyType.CONTRADICTION: "Reconcile conflicting statements or revise position.",
            FallacyType.INCOMPLETE_REASONING: "Provide complete justification for conclusions.",
        }
    
    def scan(self, text: str) -> List[FallacyDetection]:
        """
        Scan text for logical fallacies using pre-compiled patterns.
        
        Args:
            text: The reasoning step content to analyze.
            
        Returns:
            List of FallacyDetection objects for all detected fallacies.
        """
        detections: List[FallacyDetection] = []
        
        # Early termination: skip if text is too short to match any pattern
        if not text or len(text) < self._max_pattern_length:
            return detections
        
        for fallacy_type, pattern_list in self._patterns.items():
            for pattern, description in pattern_list:
                match = pattern.search(text)
                if match:
                    detections.append(
                        FallacyDetection(
                            fallacy_type=fallacy_type,
                            severity=self._assess_severity(fallacy_type, match.group()),
                            step_number=0,  # Set by caller
                            description=description,
                            suggestion=self._suggestions.get(
                                fallacy_type, 
                                "Review the reasoning step for logical validity."
                            ),
                            affected_text=match.group()
                        )
                    )
        
        return detections
    
    @staticmethod
    def _assess_severity(fallacy_type: FallacyType, matched_text: str) -> str:
        """
        Heuristic severity assessment based on match characteristics.
        
        Args:
            fallacy_type: The type of fallacy detected.
            matched_text: The text that matched the pattern.
            
        Returns:
            Severity level: "low", "medium", "high", or "critical".
        """
        if len(matched_text) > 50:
            return "critical"
        if fallacy_type in (FallacyType.CONTRADICTION, FallacyType.BEGGING_THE_QUESTION):
            return "high"
        if fallacy_type in (FallacyType.CIRCULAR_REASONING, FallacyType.NON_SEQUITUR):
            return "high"
        return "medium"
    
    def scan_batch(self, steps: List[ReasoningStep]) -> List[FallacyDetection]:
        """
        Scan multiple reasoning steps in a single batch.
        
        Args:
            steps: List of ReasoningStep objects to analyze.
            
        Returns:
            List of FallacyDetection objects with step numbers assigned.
        """
        all_detections: List[FallacyDetection] = []
        
        for step in steps:
            step_detections = self.scan(step.content)
            for detection in step_detections:
                detection.step_number = step.step_number
            all_detections.extend(step_detections)
        
        return all_detections


