# CHAIN-OF-VERIFICATION ENGINE
# ═══════════════════════════════════════════════════════════════════════════

class ChainOfVerification:
    """
    Main Chain-of-Verification engine.
    
    Orchestrates the 3-stage verification process:
    1. Reasoning extraction from LLM output
    2. Fallacy detection using the optimized matcher
    3. Verification scoring and correction suggestions
    """
    
    def __init__(
        self,
        threshold: float = 0.7,
        matcher: Optional[FallacyMatcher] = None
    ) -> None:
        """
        Initialize the CoV engine.
        
        Args:
            threshold: Minimum score (0.0-1.0) for verification to pass.
            matcher: Optional custom FallacyMatcher instance.
        """
        self.threshold = threshold
        self._matcher = matcher or FallacyMatcher()
    
    def extract_reasoning_steps(self, llm_output: str) -> List[ReasoningStep]:
        """
        Parse reasoning steps from LLM output.
        
        Expects output with numbered steps (e.g., "1. First premise...").
        
        Args:
            llm_output: Raw text output from the LLM.
            
        Returns:
            List of ReasoningStep objects.
        """
        steps: List[ReasoningStep] = []
        
        # Pattern to match numbered steps
        step_pattern = re.compile(
            r"(?:^|\n)\s*(\d+)[.)]\s+(.+?)(?=\n\s*\d+[.)]\s+|\Z)",
            re.DOTALL
        )
        
        for match in step_pattern.finditer(llm_output):
            step_number = int(match.group(1))
            content = match.group(2).strip()
            
            # Extract premises (sentences ending with period)
            sentences = re.split(r'(?<=[.!?])\s+', content)
            premises = [s for s in sentences if s and not s.endswith('?')]
            
            # Last sentence is likely the conclusion
            conclusion = sentences[-1] if sentences else ""
            
            steps.append(
                ReasoningStep(
                    step_number=step_number,
                    content=content,
                    premises=premises[:-1] if len(premises) > 1 else premises,
                    conclusion=conclusion
                )
            )
        
        return steps
    
    def _compute_verification_score(
        self,
        steps: List[ReasoningStep],
        detections: List[FallacyDetection]
    ) -> float:
        """
        Compute a verification score based on detected fallacies.
        
        Scoring logic:
        - Start with 1.0 (perfect)
        - Deduct based on fallacy severity
        - Deduct for incomplete reasoning
        
        Args:
            steps: The reasoning steps being verified.
            detections: Detected fallacies.
            
        Returns:
            Score between 0.0 and 1.0.
        """
        if not steps:
            return 0.0
        
        score = 1.0
        
        # Severity-based deductions
        severity_weights = {
            "low": 0.05,
            "medium": 0.1,
            "high": 0.2,
            "critical": 0.3,
        }
        
        for detection in detections:
            score -= severity_weights.get(detection.severity, 0.1)
        
        # Deduct for incomplete reasoning (no conclusion)
        for step in steps:
            if not step.conclusion:
                score -= 0.1
        
        # Clamp to [0.0, 1.0]
        return max(0.0, min(1.0, score))
    
    def verify(
        self,
        llm_output: str,
        reasoning_steps: Optional[List[ReasoningStep]] = None
    ) -> VerificationResult:
        """
        Run the full Chain-of-Verification process.
        
        Args:
            llm_output: Raw LLM output text.
            reasoning_steps: Optional pre-extracted reasoning steps.
                            If None, steps are extracted from llm_output.
                            
        Returns:
            VerificationResult with pass/fail status, score, and detections.
        """
        # Stage 1: Extract reasoning steps
        steps = reasoning_steps or self.extract_reasoning_steps(llm_output)
        
        if not steps:
            logger.warning("No reasoning steps extracted from LLM output")
            return VerificationResult(
                passed=False,
                score=0.0,
                reasoning_steps=[],
                detected_fallacies=[],
                suggestions=["No reasoning steps found in output."]
            )
        
        # Stage 2: Detect fallacies
        detections = self._matcher.scan_batch(steps)
        
        # Stage 3: Compute score and generate suggestions
        score = self._compute_verification_score(steps, detections)
        passed = score >= self.threshold
        
        suggestions = [d.suggestion for d in detections]
        
        # Generate corrected reasoning if fallacies were found
        corrected_reasoning = None
        if detections:
            corrected_reasoning = self._generate_correction(steps, detections)
        
        result = VerificationResult(
            passed=passed,
            score=score,
            reasoning_steps=steps,
            detected_fallacies=detections,
            suggestions=suggestions,
            corrected_reasoning=corrected_reasoning
        )
        
        logger.info(
            "CoV verification complete: passed=%s, score=%.2f, fallacies=%d",
            passed, score, len(detections)
        )
        
        return result
    
    def _generate_correction(
        self,
        steps: List[ReasoningStep],
        detections: List[FallacyDetection]
    ) -> str:
        """
        Generate a corrected version of the reasoning chain.
        
        Args:
            steps: Original reasoning steps.
            detections: Detected fallacies.
            
        Returns:
            Corrected reasoning text with annotations.
        """
        corrected_lines: List[str] = []
        
        # Group detections by step
        detections_by_step: Dict[int, List[FallacyDetection]] = defaultdict(list)
        for detection in detections:
            detections_by_step[detection.step_number].append(detection)
        
        for step in steps:
            corrected_lines.append(f"{step.step_number}. {step.content}")
            
            # Add correction annotations for this step
            step_detections = detections_by_step.get(step.step_number, [])
            for detection in step_detections:
                corrected_lines.append(
                    f"   [CORRECTION] {detection.fallacy_type.value}: "
                    f"{detection.suggestion}"
                )
        
        return "\n".join(corrected_lines)


