# BACKWARD-COMPATIBLE INTERFACE
# ═══════════════════════════════════════════════════════════════════════════

# Module-level singleton for backward compatibility
_engine = ChainOfVerification()


def verify_reasoning(
    llm_output: str,
    reasoning_steps: Optional[List[ReasoningStep]] = None
) -> VerificationResult:
    """
    Backward-compatible function interface for CoV verification.
    
    Args:
        llm_output: Raw LLM output text.
        reasoning_steps: Optional pre-extracted reasoning steps.
        
    Returns:
        VerificationResult.
    """
    return _engine.verify(llm_output, reasoning_steps)


def detect_fallacies(text: str) -> List[FallacyDetection]:
    """
    Backward-compatible function to detect fallacies in a single text.
    
    Args:
        text: Text to analyze.
        
    Returns:
        List of FallacyDetection objects.
    """
    matcher = FallacyMatcher()
    return matcher.scan(text)


