def get_pattern_stats() -> Dict[str, Any]:
    """
    Get statistics about the compiled pattern engine.
    
    Returns:
        Dictionary with pattern count, compilation info, and matcher stats.
    """
    total_patterns = sum(len(patterns) for patterns in COMPILED_FALLACY_PATTERNS.values())
    return {
        "total_patterns": total_patterns,
        "fallacy_types": len(FALLACY_PATTERNS),
        "patterns_per_type": {
            fallacy_type.value: len(patterns)
            for fallacy_type, patterns in COMPILED_FALLACY_PATTERNS.items()
        },
        "max_pattern_length": max(
            len(p.pattern) for patterns in COMPILED_FALLACY_PATTERNS.values()
            for p, _ in patterns
        ),
        "compiled_at_import": True,
        "re_ignorecase": True,
    }


